import "./App.css";
import React, { useState } from 'react';
import axios from 'axios';

function App() {
  const [searchTerm, setSearchTerm] = useState('');
  const [result, setResult] = useState('');

  const handleSearch = async () => {
    try {
      print(searchTerm)
      const response = await axios.post('http://localhost:5000/search', { searchTerm });
      setResult(response.data.result);
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
      <div className="title"><h1>EcoCatch</h1></div>
      <div class="wrap">
        <div class="search">
           <input type="text" class="searchTerm" placeholder="Search by waterbody..."/>
           <button type="submit" class="searchButton" onClick={handleSearch} value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}>
            Submit
          </button>

        </div>
     </div>
      </header>
    </div>
  );
}

export default App;
